const meta = $input.first().json.output || $input.first().json;
const brief = $('Brief EN').first().json;

const target = String(brief.targetSource || 'EN').toUpperCase();

// Ukrainian national transliteration, Cabinet of Ministers Resolution 55 of 2010.
// This is the standard Ukrainian sites and passports use.
const UK_START = { 'є': 'ye', 'ї': 'yi', 'й': 'y', 'ю': 'yu', 'я': 'ya' };
const UK = {
  'а': 'a', 'б': 'b', 'в': 'v', 'г': 'h', 'ґ': 'g', 'д': 'd', 'е': 'e', 'є': 'ie',
  'ж': 'zh', 'з': 'z', 'и': 'y', 'і': 'i', 'ї': 'i', 'й': 'i', 'к': 'k', 'л': 'l',
  'м': 'm', 'н': 'n', 'о': 'o', 'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u',
  'ф': 'f', 'х': 'kh', 'ц': 'ts', 'ч': 'ch', 'ш': 'sh', 'щ': 'shch', 'ь': '',
  'ю': 'iu', 'я': 'ia', "'": '', '’': '', 'ъ': ''
};

// Russian, Bulgarian, Serbian, Belarusian, Macedonian.
const CY = {
  'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'ґ': 'g', 'д': 'd', 'е': 'e', 'ё': 'e',
  'ж': 'zh', 'з': 'z', 'и': 'i', 'і': 'i', 'ї': 'yi', 'й': 'y', 'к': 'k', 'л': 'l',
  'м': 'm', 'н': 'n', 'о': 'o', 'п': 'p', 'р': 'r', 'с': 's', 'т': 't', 'у': 'u',
  'ф': 'f', 'х': 'kh', 'ц': 'ts', 'ч': 'ch', 'ш': 'sh', 'щ': 'shch', 'ъ': '',
  'ы': 'y', 'ь': '', 'э': 'e', 'ю': 'yu', 'я': 'ya', 'є': 'ye', 'ў': 'u',
  'ђ': 'dj', 'ј': 'j', 'љ': 'lj', 'њ': 'nj', 'ћ': 'c', 'џ': 'dz',
  'ѓ': 'gj', 'ѕ': 'dz', 'ќ': 'kj', "'": '', '’': ''
};

// Greek, ELOT 743.
const EL = {
  'α': 'a', 'β': 'v', 'γ': 'g', 'δ': 'd', 'ε': 'e', 'ζ': 'z', 'η': 'i', 'θ': 'th',
  'ι': 'i', 'κ': 'k', 'λ': 'l', 'μ': 'm', 'ν': 'n', 'ξ': 'x', 'ο': 'o', 'π': 'p',
  'ρ': 'r', 'σ': 's', 'ς': 's', 'τ': 't', 'υ': 'y', 'φ': 'f', 'χ': 'ch', 'ψ': 'ps',
  'ω': 'o', 'ά': 'a', 'έ': 'e', 'ή': 'i', 'ί': 'i', 'ό': 'o', 'ύ': 'y', 'ώ': 'o',
  'ϊ': 'i', 'ϋ': 'y', 'ΐ': 'i', 'ΰ': 'y'
};

// Latin letters that survive diacritic stripping unchanged and need their own mapping.
const LATIN = {
  'ß': 'ss', 'ø': 'o', 'æ': 'ae', 'œ': 'oe', 'ł': 'l', 'đ': 'd', 'ð': 'd',
  'þ': 'th', 'ı': 'i', 'ħ': 'h', 'ŧ': 't', 'ŋ': 'n', 'ə': 'e'
};

// German spells the umlauts out rather than dropping the diaeresis, so Händler
// becomes haendler rather than handler.
const DE = { 'ä': 'ae', 'ö': 'oe', 'ü': 'ue', 'ß': 'ss' };

const isCyrillic = s => /[Ѐ-ӿ]/.test(s);
const isGreek = s => /[Ͱ-Ͽἀ-῿]/.test(s);

function stripDiacritics(s) {
  const german = target.startsWith('DE');
  let out = '';
  for (const ch of s) {
    const lower = ch.toLowerCase();
    if (german && DE[lower] !== undefined) out += DE[lower];
    else if (LATIN[lower] !== undefined) out += LATIN[lower];
    else out += ch;
  }
  return out.normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function translitCyrillic(s, ukrainian) {
  const map = ukrainian ? UK : CY;
  let out = '';
  let atWordStart = true;
  for (const ch of s) {
    const lower = ch.toLowerCase();
    if (ukrainian && atWordStart && UK_START[lower] !== undefined) {
      out += UK_START[lower];
    } else if (map[lower] !== undefined) {
      out += map[lower];
    } else {
      out += ch;
    }
    atWordStart = !/[\p{L}\p{N}]/u.test(ch);
  }
  // зг is the one digraph the standard treats specially, to keep it apart from ж.
  return ukrainian ? out.replace(/zh(?=h)/g, 'zg') : out;
}

function translitGreek(s) {
  let out = '';
  for (const ch of s) {
    const lower = ch.toLowerCase();
    out += (EL[lower] !== undefined ? EL[lower] : ch);
  }
  return out;
}

function transliterate(s) {
  let out = s;
  if (isCyrillic(out)) out = translitCyrillic(out, target === 'UK');
  if (isGreek(out)) out = translitGreek(out);
  return stripDiacritics(out);
}

function slugify(s, maxWords) {
  const cleaned = String(s || '')
    .toLowerCase()
    .replace(/['’`"]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .replace(/-{2,}/g, '-');
  if (!cleaned) return '';
  const words = cleaned.split('-').filter(Boolean);
  return words.slice(0, maxWords || 6).join('-');
}

const rawSlug = String(meta.url_slug || '');
const converted = transliterate(rawSlug);

// Scripts with no reliable romanisation in plain JS: CJK, Arabic, Hebrew, Thai,
// Devanagari. They come through transliterate() untouched, so anything non-ASCII
// left here means the slug cannot be romanised and only its stray Latin
// characters would survive. Fall back to the English rendering of the core
// keyword, which Brief EN already holds from the DeepL round trip.
const romanisable = converted && !/[^\x00-\x7F]/.test(converted);

let slug = romanisable ? slugify(converted) : '';
let source = 'transliterated';

if (!slug) {
  slug = slugify(transliterate(brief.coreKeyword || brief.h1 || ''));
  source = 'englishCoreKeyword';
}
if (!slug) {
  throw new Error(`Slug Fixer: could not build a slug. Raw slug was "${rawSlug}", English core keyword was "${brief.coreKeyword}".`);
}

return [{ json: {
  slug,
  rawSlug,
  slugSource: slug === slugify(rawSlug) ? 'asWritten' : source,
  meta_title: String(meta.meta_title || ''),
  meta_description: String(meta.meta_description || '')
} }];

const T = {};

T.user = `Write the URL slug and meta description for the following page:`;

T.system = `You are an SEO copywriter. Your task is to write the URL slug, the meta title and the meta description for a __F_pageTypeLabel__. You MUST follow the strict requirements exactly and then provide the output in JSON.

<strict_requirements>

**URL slug rules:**
- Write the slug in the same language and script as the page, using the words of the core keyword.
- Separate words with hyphens. Use no capital letters and no punctuation beyond the hyphens.
- The URL slug MUST include the core keyword: {{CORE_KEYWORD}}
- Do NOT use prepositions or articles unless one is part of the core keyword.
- Keep the slug to a maximum of six words.
- If words or letters are separated by a dot, merge them into one word.
- The slug must describe this page and no other page in the set.
- Do NOT romanise or transliterate anything yourself. A later step converts the slug to Latin characters using the official transliteration standard for this language, so choose the right words and leave the characters exactly as the language writes them.

**Meta title rules:**
- Maximum 60 characters including spaces.
- MUST include the core keyword: {{CORE_KEYWORD}}
- Place the core keyword as close to the front as reads naturally.
- State the outcome or the fit rather than the technology.
- Never use a superlative, a promotional adjective or an exclamation mark.
- Do not append the brand name. The CMS adds it.

**Meta description rules:**
- Maximum 150 characters including spaces and punctuation.
- MUST name the client explicitly: {{CLIENT_NAME}}
- MUST describe how {{CLIENT_NAME}} provides what this page is about. Name the client, then what they provide, then what the reader gets from it.
- Write it as a factual statement of what {{CLIENT_NAME}} does, not as an invitation to read the page. Never write "learn how", "discover how", "find out how" or "see how".
- MUST include the core keyword within the first 60 characters, and the keyword must not be the opening word or phrase. Opening with the client's name is the natural way to satisfy this.
- Use the client's name exactly as written above. Never abbreviate it, expand it, translate it, or add a legal suffix it does not already have.
- Reproduce the core keyword exactly as written above, character for character.
- Address the reader directly as "you" where the sentence needs a second party.
- Use plain language.
- Never use generic or hyped words used by sales people.
- Never use an intensifier such as very, really, absolutely, clearly or obviously.
- Never use a vague attribution such as "experts say" or "studies show".
- Never use AI vocabulary such as leverage, robust, seamless, unlock or transform.
- Never use an -ing pile-up such as "helping you understand" or "providing insights into".
- Never list exactly three parallel items in a comma series.
- Never use a negative parallelism such as "it's not just X, it's Y".
- Never use a tailing negation such as "no guesswork".
- Never use an em dash, a semicolon or an ampersand.
- Never claim a result, a number or a certification that is not already on the page.

Shape to follow: "[Client] provides [what, carrying the core keyword] so you [the concrete outcome]."
Worked example: "Chairside provides practice management software for dental clinics, so eligibility checks land on the appointment before the patient arrives."
</strict_requirements>

Provide the output in the JSON format.`;

const fill = (t, vals) => Object.entries(vals).reduce(
  (s, [k, v]) => s.split('__F_' + k + '__').join(v == null ? '' : String(v)), t);

const brief = $('Brief EN').first().json;
const req = $('request-parser').first().json;

const clientName = (req.clientName || brief.clientName || '').trim();
if (!clientName) {
  throw new Error('Prep Meta: clientName is required because the meta description must name the client.');
}

const coreKeyword = (brief.isLang ? brief.originalCoreKeyword : brief.coreKeyword) || req.coreKeyword || '';

const prompts = {
  metaUser: T.user,
  metaSystem: fill(T.system, {
    pageTypeLabel: brief.isIndustry ? 'industry landing page' : 'solution landing page'
  })
};

const fieldNames = Object.keys(prompts);

return [{ json: {
  prompts,
  clientName,
  coreKeyword,
  fieldNames,
  fieldTexts: fieldNames.map(n => prompts[n]),
  targetSource: brief.targetSource
} }];
